    var pixX = i - (pixY * i32(dimensions.x));
    var pixelWidth = 1.0 / dimensions.x;
    var pixelHeight = 1.0 / dimensions.y;
    var u = (f32(pixX) + 0.5) * pixelWidth; // sample from center of pixel
    var v = (f32(pixY) + 0.5) * pixelHeight;
    return vec2<f32>(u, v);
